use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering};
static CALLS: AtomicUsize = AtomicUsize::new(0);
static BYTES: AtomicUsize = AtomicUsize::new(0);
struct Counter;
unsafe impl GlobalAlloc for Counter {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        CALLS.fetch_add(1, Ordering::Relaxed);
        BYTES.fetch_add(layout.size(), Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }
    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        CALLS.fetch_add(1, Ordering::Relaxed);
        BYTES.fetch_add(layout.size(), Ordering::Relaxed);
        unsafe { System.alloc_zeroed(layout) }
    }
    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        CALLS.fetch_add(1, Ordering::Relaxed);
        BYTES.fetch_add(size, Ordering::Relaxed);
        unsafe { System.realloc(ptr, layout, size) }
    }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) { unsafe { System.dealloc(ptr, layout) } }
}
#[global_allocator]
static ALLOCATOR: Counter = Counter;
fn main() {
    let sources=["typedef int T; struct S {int x;}; extern int f(T);", "int f(int n) { typedef int A[n]; A a; { long n; n=2; } for(int i=0;i<3;i++){ int x=i; } return sizeof a; }", "enum E { A=0, B=17 }; struct S { char a; unsigned b:3; double c; }; int f(int *p){ return *p+1; }"];
    for target in toucan_target::Target::ALL {
        for (index,source) in sources.iter().enumerate() {
            drop(toucan_semantic::analyze(source,target).unwrap());
            CALLS.store(0,Ordering::Relaxed); BYTES.store(0,Ordering::Relaxed);
            let unit=toucan_semantic::analyze(source,target).unwrap();
            let calls=CALLS.load(Ordering::Relaxed);let bytes=BYTES.load(Ordering::Relaxed);
            println!("semantic {target:?} {index}: {calls} {bytes} {}",unit.declarations.len());
        }
        drop(toucan::Config::new(target));
        CALLS.store(0,Ordering::Relaxed); BYTES.store(0,Ordering::Relaxed);
        let config=toucan::Config::new(target);
        let calls=CALLS.load(Ordering::Relaxed);let bytes=BYTES.load(Ordering::Relaxed);
        println!("config {target:?}: {calls} {bytes} {}",config.preprocessor.defines.len());
    }
}

