use std::{hint::black_box,time::Instant};
fn main(){
 let args=std::env::args().collect::<Vec<_>>();
 let source=std::fs::read_to_string(&args[1]).unwrap();let iterations:usize=args[2].parse().unwrap();
 toucan_semantic::with_parser_stack(||{
  for _ in 0..5 {black_box(toucan_semantic::analyze(black_box(&source),toucan_target::Target::X86_64UnknownLinuxGnu).unwrap());}
  let start=Instant::now();let mut declarations=0;
  for _ in 0..iterations {let unit=toucan_semantic::analyze(black_box(&source),toucan_target::Target::X86_64UnknownLinuxGnu).unwrap();declarations=black_box(unit.declarations.len());drop(black_box(unit));}
  println!("{} {} {}",start.elapsed().as_nanos(),iterations,declarations);
 }).unwrap();
}
